preConditionHook:
// CONSOLIDATION BREAKOUT BAR HIGH CLOSE (Brian's notes ON-33, #33). After the
// most recent bull breakout bar [bullK], no close since (bars 1 .. bullK - 1)
// has been above the breakout bar's own high; this bar closes above it: long --
// the first close beyond the breakout candle. Short mirrors at a bear
// breakout bar's low. A newer breakout replaces an older one; maxWaitBars is
// the only bound (the note gives no invalidation).
// MultiWalk's WFSafe_AvgTrueRange is a ROLLING accumulator, not a fresh N-term
// sum: seeded with a full sum on the study's first calculated bar, thereafter
// S += TrueRange - TrueRange[Length] as TWO statements (EL evaluates
// S[1] + in - out left to right; folding it rounds differently), re-seeding
// when the length changes. Same block as RangeWidthBelowAtrMultiple and
// AtrProfitTarget (the reference).
if (atrLength != (int)zoneBars) {
    atrSum = 0.0;
    for (int i = 0; i < (int)zoneBars; ++i) {
        double hi = high[i] > close[i + 1] ? high[i] : close[i + 1];
        double lo = low[i] < close[i + 1] ? low[i] : close[i + 1];
        atrSum += hi - lo;
    }
    atrLength = (int)zoneBars;
} else {
    const int out = (int)zoneBars;
    double hiIn = high[0] > close[1] ? high[0] : close[1];
    double loIn = low[0] < close[1] ? low[0] : close[1];
    double hiOut = high[out] > close[out + 1] ? high[out] : close[out + 1];
    double loOut = low[out] < close[out + 1] ? low[out] : close[out + 1];
    atrSum += hiIn - loIn;
    atrSum -= hiOut - loOut;
}
atr = atrSum / (int)zoneBars;
// CONSOLIDATION BREAKOUT SCAN -- one inlined form, copied verbatim into
// ConsolidationBreakoutFirstRetest and ConsolidationBreakoutBarHighClose
// (Brian's notes ON-32/ON-33, built on ON-30-a/ON-30-b). For kk = 1 ..
// maxWaitBars, bar [kk] is a breakout bar when the zoneBars bars ending at
// [kk + 1] are a consolidation zone (Highest - Lowest <= zoneAtrMultiple x
// ATR(zoneBars) read at [kk + 1], RangeWidthBelowAtrMultiple at lag kk + 1)
// and bar [kk] opened inside the zone and closed at least breakoutAtr x the
// same ATR beyond it. The first hit walking back is the most recent; bull and
// bear tracked separately.
//
// EL reads atrVal[kk + 1], the VARIABLE's own history, zero before the first
// evaluated bar: mirrored as a zero-seeded ring buffer of lags
// 0 .. maxWaitBars + 1 (AtrAtExtreme / AtrRising are the reference),
// re-seeded if the depth changes. This bar's value goes in first, so lag L
// sits L slots behind the newest slot.
if (atrHistory.size() != (std::size_t)((int)maxWaitBars + 2)) {
    atrHistory.assign((std::size_t)((int)maxWaitBars + 2), 0.0);
    atrCursor = 0;
}
histLen = atrHistory.size();
atrHistory[atrCursor] = atr;
atrCursor = (atrCursor + 1) % histLen;
bullK = 0;
bearK = 0;
bullHi = 0.0;
bullLo = 0.0;
bearHi = 0.0;
bearLo = 0.0;
bullBarHigh = 0.0;
bearBarLow = 0.0;
for (int kk = 1; kk <= (int)maxWaitBars; ++kk) {
    zh = high[kk + 1];
    zl = low[kk + 1];
    for (int ii = 1; ii <= (int)zoneBars - 1; ++ii) {
        if (el_gt(high[kk + 1 + ii], zh)) zh = high[kk + 1 + ii];
        if (el_lt(low[kk + 1 + ii], zl)) zl = low[kk + 1 + ii];
    }
    atrK = atrHistory[(atrCursor + histLen - 1 - (std::size_t)(kk + 1)) % histLen];
    if (el_le(zh - zl, zoneAtrMultiple * atrK) && el_ge(open[kk], zl) && el_le(open[kk], zh)) {
        if (bullK == 0 && el_ge(close[kk], zh + breakoutAtr * atrK)) {
            bullK = kk;
            bullHi = zh;
            bullLo = zl;
            bullBarHigh = high[kk];
        }
        if (bearK == 0 && el_le(close[kk], zl - breakoutAtr * atrK)) {
            bearK = kk;
            bearHi = zh;
            bearLo = zl;
            bearBarLow = low[kk];
        }
    }
}
bullFirst = bullK > 0;
for (int jj = 1; jj < bullK; ++jj) {
    if (el_gt(close[jj], bullBarHigh)) bullFirst = false;
}
bearFirst = bearK > 0;
for (int jj = 1; jj < bearK; ++jj) {
    if (el_lt(close[jj], bearBarLow)) bearFirst = false;
}
